style.css:
@-moz-document domain("roblox.com") {
html {
        background-image: linear-gradient(rgba(0, 0, 0, 0.52), rgba(0, 0, 0, 0.60)), url("https://tr.rbxcdn.com/180DAY-0e124bfe8ed4a3e29741a9aef4ac9ede/420/420/Image/Webp/noFilter") !important;
        background-size: cover !important;
        background-position: center center !important;
        background-attachment: fixed !important;
        background-repeat: no-repeat !important;
    }
    body, .rbx-body, #wrap, .container-main, .content, #rbx-body > div, .content > div, main, [class*="background"], [class*="container"] {
        background-color: transparent !important;
        background-image: none !important;
    }
    .game-card-container, .rbx-header, .rbx-left-col, .section-content {
        background-color: rgba(15, 17, 20, 0.40) !important;
        border-radius: 10px !important;
    }
}
